					}
					childMessage := waitChannelAnchorReceipt(t, db, child)
					childToken, found := telegramCallbackToken(h.provider.Delivery(childMessage-1), "approve")
					if !found || childToken == token {
						t.Fatal("fork delivery reused parent control identity")
					}
					readParent := func() [3]string {
						var state [3]string
						if err := db.QueryRow(`SELECT status,COALESCE(verdict,''),CAST(updated_at AS TEXT) FROM decision_cards WHERE card_id=$1`, card).Scan(&state[0], &state[1], &state[2]); err != nil {
							t.Fatal(err)
						}
						return state
					}
					parentBefore := readParent()
					_, childIntent := postChannelSourceControlObserved(t, callback, signing, intentIdentity, child, childToken, childMessage)
					reader := openChannelAnchorObservation(t, h)
					deadline := time.Now().Add(5 * time.Second)
					for {
						settled, result := observeChannelDisposition(t, reader, childIntent, "unsupported")
						if settled {
							break
						}
						if time.Now().After(deadline) {
							var status, verdict string
							cardErr := db.QueryRow(`SELECT status,COALESCE(verdict,'') FROM decision_cards WHERE card_id=$1`, child).Scan(&status, &verdict)
							var decisions int
							eventErr := db.QueryRow(`SELECT COUNT(*) FROM events WHERE run_id=$1 AND event_name='mailbox.card_decided'`, fork.ForkRunID).Scan(&decisions)
							t.Fatalf("selected-fork callback %+v lacks terminal unsupported disposition: observation=%+v card_status=%s verdict=%s card_err=%v decisions=%d event_err=%v", childIntent, result, status, verdict, cardErr, decisions, eventErr)
						}
						time.Sleep(20 * time.Millisecond)
					}
					if err := reader.Close(); err != nil {
						t.Fatal(err)
					}
					var status string
					if err := db.QueryRow(`SELECT status FROM decision_cards WHERE card_id=$1`, child).Scan(&status); err != nil || status != "pending" {
						t.Fatalf("fork callback bypassed selected control refusal: status=%s err=%v", status, err)
					}
					postChannelSourceControl(t, callback, signing, child, childToken, childMessage)
					ordinary := requireServedEventPublishRPCResult(t, h.rpcEndpoint(), map[string]any{"event_name": "work.requested", "bundle_hash": hash, "payload": map[string]any{"seed": true}, "idempotency_key": uuid.NewString()})
					ordinaryCard := waitChannelAnchorCard(t, db, ordinary.RunID, decisioncard.AnchorKindStageGate, "reviews")
					ordinaryMessage := waitChannelAnchorReceipt(t, db, ordinaryCard)
					ordinaryToken, ok := telegramCallbackToken(h.provider.Delivery(ordinaryMessage-1), "approve")
					if !ok {
						t.Fatal("normal run lost decision control")
					}
					postChannelSourceControl(t, callback, signing, ordinaryCard, ordinaryToken, ordinaryMessage)
					waitChannelAnchorDecision(t, db, ordinaryCard)
					waitChannelDeliverySendsSettled(t, db, backend)
					h.stop(t)
					h.start(t)
					callback, signing, _ = h.provider.Registration()
					postChannelSourceControl(t, callback, signing, child, childToken, childMessage)
					var verdict string
					var events, drafts int
					if err := db.QueryRow(`SELECT status,COALESCE(verdict,'') FROM decision_cards WHERE card_id=$1`, child).Scan(&status, &verdict); err != nil || status != "pending" || verdict != "" {
						t.Fatalf("fork replay/restart changed child: %s/%s %v", status, verdict, err)
					}
					if err := db.QueryRow(`SELECT COUNT(*) FROM events WHERE run_id=$1 AND event_name='mailbox.card_decided'`, fork.ForkRunID).Scan(&events); err != nil || events != 0 {
						t.Fatalf("fork restart emitted a decision: %d %v", events, err)
					}
					if err := db.QueryRow(`SELECT COUNT(*) FROM decision_card_input_drafts WHERE card_id=$1`, child).Scan(&drafts); err != nil || drafts != 0 {
						t.Fatalf("upstream fork refusal created a draft: %d %v", drafts, err)
					}
					if readParent() != parentBefore {
						t.Fatal("child refusal or normal-run control mutated the frozen parent card")
					}
				}
				if after := readChannelSourceHistory(t, db, card); after != frozen {
					t.Fatal("source lifecycle changed historical receipt/render evidence")
				}
			})
		}
	}
}

func channelSourceControlPayload(card, token string, messageID int) map[string]any {
	return map[string]any{"update_id": 976000 + messageID, "callback_query": map[string]any{"id": "source-" + card, "from": map[string]any{"id": 7000}, "message": map[string]any{"message_id": messageID, "chat": map[string]any{"id": 1001, "type": "private"}}, "data": token}}
}

Before:
func postChannelSourceControl(t *testing.T, callback, signing, card, token string, messageID int) int {
	t.Helper()
	return postChannelSourceUpdate(t, callback, signing, map[string]any{"update_id": 976000 + messageID, "callback_query": map[string]any{"id": "source-" + card, "from": map[string]any{"id": 7000}, "message": map[string]any{"message_id": messageID, "chat": map[string]any{"id": 1001, "type": "private"}}, "data": token}})
}

After:
func postChannelSourceControl(t *testing.T, callback, signing, card, token string, messageID int) int {
	t.Helper()
	return postChannelSourceUpdate(t, callback, signing, channelSourceControlPayload(card, token, messageID))
}

func postChannelSourceControlObserved(t *testing.T, callback, signing string, identity channeldelivery.IntentObservationQuery, card, token string, messageID int) (int, channeldelivery.IntentObservationQuery) {
	t.Helper()
	payload := channelSourceControlPayload(card, token, messageID)
	query := objectIntentQuery(identity, channeldelivery.IntentAction, fmt.Sprint(payload["update_id"]))
	return postChannelSourceUpdate(t, callback, signing, payload), query
}

func captureChannelIntentIdentity(t *testing.T, h *channelOnboardingE2EHarness) channeldelivery.IntentObservationQuery {
	t.Helper()
	var channels struct {
		Channels []channelonboarding.ConnectedChannelReadback `json:"channels"`
	}
	requireServedJSONRPCResult(t, h.rpcEndpoint(), "channel.list", map[string]any{}, &channels)
	if len(channels.Channels) != 1 {
		t.Fatalf("intent proof needs the exact ingress identity, not guessed binding: %+v", channels)
	}
	row := channels.Channels[0]
	if row.Identity.Interface.Validate() != nil {
		t.Fatalf("intent ingress readback has incomplete interface: %+v", row)
	}
	provider := ""
	if row.Activation != nil {
		if row.Identity.Interface != row.Activation.Interface {
			t.Fatalf("intent interface contradicts its retained activation: %+v", row)
		}
		provider = row.Activation.Provider
	} else if row.Operation == nil && row.Recovery != nil {
		provider = row.Recovery.Provider
	}
	if provider == "" || row.Recovery != nil && row.Recovery.Provider != provider {
		t.Fatalf("intent ingress has missing or contradictory provider evidence: %+v", row)
	}
	return channeldelivery.IntentObservationQuery{Provider: provider, InterfaceKey: row.Identity.Interface.Key()}
}
